TYPE E_P20_State :
(
    IDLE,
    MOVE_TO_WASH,
    WAIT_WASH,
    MOVE_TO_WEIGHT,
    WAIT_WEIGHT,
    MOVE_TO_FIRING,
    WAIT_FIRING,
    MOVE_TO_OUTPUT,
    AT_OUTPUT,
    REJECT_WAIT
);
END_TYPE

FUNCTION_BLOCK FB_P20
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorFeed : BOOL;
    SensorWash : BOOL;
    SensorWeight : BOOL;
    SensorFiring : BOOL;
    SensorOutput : BOOL;
    washComplete : BOOL;
    weightComplete : BOOL;
    weight : REAL;
    firingComplete : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL;
    MotorReverse : BOOL;
    kick : BOOL;
    CompletionLight : BOOL;
    firingTemp : REAL;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    State : E_P20_State := IDLE;
    KickedAtOutput : BOOL := FALSE;
    RejectPending : BOOL := FALSE;
END_VAR

(* CONFLICT NOTICE: The original text says an unqualified weight at the weighing station
   initiates kick. The formal specification C2 requires G(kick -> SensorOutput), and K4
   places kick at the finished-product station. This implementation follows C2/K4:
   kick is only a one-scan pulse at the finished-product station before CompletionLight.
   An unqualified weight sets RejectPending and stops at the weighing station without
   energizing kick, to avoid violating C2. The conflict is preserved and reported. *)

IF FirstScan THEN
    MotorForward := FALSE;
    MotorReverse := FALSE;
    kick := FALSE;
    CompletionLight := FALSE;
    firingTemp := 0.0;
    FirstScan := FALSE;
ELSE
    MotorForward := FALSE;
    MotorReverse := FALSE;
    kick := FALSE;
    CompletionLight := FALSE;

    IF NOT Mode THEN
        (* Manual mode: interlocked forward/reverse jog control *)
        MotorForward := ForwardButton AND NOT ReverseButton;
        MotorReverse := ReverseButton AND NOT ForwardButton;
        kick := FALSE;
        CompletionLight := FALSE;
    ELSE
        (* Automatic mode: sequential station state machine *)
        CASE State OF
        IDLE:
            IF SensorFeed THEN
                MotorForward := TRUE;
                State := MOVE_TO_WASH;
            END_IF;

        MOVE_TO_WASH:
            MotorForward := TRUE;
            IF SensorWash THEN
                MotorForward := FALSE;
                State := WAIT_WASH;
            END_IF;

        WAIT_WASH:
            IF SensorWash AND washComplete THEN
                MotorForward := TRUE;
                State := MOVE_TO_WEIGHT;
            END_IF;

        MOVE_TO_WEIGHT:
            MotorForward := TRUE;
            IF SensorWeight THEN
                MotorForward := FALSE;
                State := WAIT_WEIGHT;
            END_IF;

        WAIT_WEIGHT:
            IF SensorWeight AND weightComplete THEN
                IF (weight >= 100.0) AND (weight <= 200.0) THEN
                    firingTemp := 500.0 + (weight - 100.0) * 0.5;
                    MotorForward := TRUE;
                    State := MOVE_TO_FIRING;
                ELSE
                    RejectPending := TRUE;
                    State := REJECT_WAIT;
                    MotorForward := FALSE;
                    MotorReverse := FALSE;
                    kick := FALSE;
                END_IF;
            END_IF;

        MOVE_TO_FIRING:
            MotorForward := TRUE;
            IF SensorFiring THEN
                MotorForward := FALSE;
                State := WAIT_FIRING;
            END_IF;

        WAIT_FIRING:
            IF SensorFiring AND firingComplete THEN
                MotorForward := TRUE;
                State := MOVE_TO_OUTPUT;
            END_IF;

        MOVE_TO_OUTPUT:
            MotorForward := TRUE;
            IF SensorOutput THEN
                MotorForward := FALSE;
                State := AT_OUTPUT;
            END_IF;

        AT_OUTPUT:
            IF SensorOutput THEN
                IF NOT KickedAtOutput THEN
                    kick := TRUE;
                    KickedAtOutput := TRUE;
                    CompletionLight := FALSE;
                ELSE
                    kick := FALSE;
                    CompletionLight := TRUE;
                END_IF;
            ELSE
                kick := FALSE;
                CompletionLight := FALSE;
                KickedAtOutput := FALSE;
                RejectPending := FALSE;
                State := IDLE;
            END_IF;

        REJECT_WAIT:
            MotorForward := FALSE;
            MotorReverse := FALSE;
            kick := FALSE;
            CompletionLight := FALSE;
            IF NOT SensorWeight THEN
                RejectPending := FALSE;
                State := IDLE;
            END_IF;

        ELSE
            State := IDLE;
        END_CASE;
    END_IF;

    (* Final safety interlocks *)
    IF MotorForward AND MotorReverse THEN
        MotorForward := FALSE;
        MotorReverse := FALSE;
    END_IF;

    IF kick AND NOT SensorOutput THEN
        kick := FALSE;
    END_IF;

    IF CompletionLight THEN
        kick := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
